import subprocess, struct
def run_r(data):
    open("/tmp/testkey","wb").write(data)
    r=subprocess.run(["./executable","-r","/tmp/testkey"], capture_output=True, text=True, timeout=3)
    line=r.stderr.strip().splitlines()[0]
    return "STRING_TOO_LONG" if "String too long" in line else ("BAD_BUF" if "Bad buf" in line else ("FAILED" if "Failed loading" in line else line))

for length in [4000,5000,6000,7000,8000,8192,8193,9000]:
    data=struct.pack(">I", length)
    print(f"{length} -> {run_r(data)}")
# binary search between 5000 and 10000
lo,hi=5000,10000
while hi-lo>100:
    mid=(lo+hi)//2
    res=run_r(struct.pack(">I", mid))
    print(f"mid {mid} -> {res}")
    if res=="STRING_TOO_LONG":
        hi=mid
    else:
        lo=mid
print(f"range {lo}-{hi}")
for length in range(lo-200, hi+200, 50):
    print(f"{length} -> {run_r(struct.pack('>I', length))}")
PY
"}

