void log_msg(const char *fmt, ...) {
    char msgbuf[2048];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(msgbuf, sizeof(msgbuf), fmt, ap);
    va_end(ap);
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char datestr[64];
    strftime(datestr, sizeof(datestr), "%b %d %H:%M:%S", tm);
    fprintf(stderr, "[%d] %s %s\n", getpid(), datestr, msgbuf);
