    int opt_keys_cap = 0;
    char *opt_D = NULL;
    int opt_R = 0;
    int opt_F = 0;
    int opt_e = 0;
    int opt_m = 0;
    int opt_w = 0;
    char *opt_G = NULL;
    int opt_s = 0;
    int opt_g = 0;
    int opt_B = 0;
    int opt_t = 0;
    char *opt_T_str = NULL;
    int opt_j = 0;
    int opt_k = 0;
