                        if (S_ISDIR(fst.st_mode)) {
                            log_msg("Error reading banner file '%s'", opt_banner);
                        } else {
                            // success, no log. But need to handle 000 perms? open would have failed with EACCES, already handled as Error reading? Wait open failure currently would be Error reading? In our code above, open failure goes to Error reading, good.
                            // For 000 file, open fails -> Error reading, matches original.
                        }
                    }
                    close(fd);
                }
            }
        }
    }

    // Group
    if (opt_G) {
        struct group *gr = getgrnam(opt_G);
        if (!gr) {
            early_exit("Early exit: Cannot restrict logins to group '%s' as the group does not exist", opt_G);
        }
    }

    // W
    long recv_window = 24576;
    if (opt_W_str) {
        long use_val;
        int need_warn;
        parse_recv_window(opt_W_str, &use_val, &need_warn);
        if (need_warn) {
            // need to determine using value: if parse failed or zero -> 24576, else if >max -> 10485760
            // parse_recv_window already sets use_val
            log_msg("Bad recv window '%s', using %ld", opt_W_str, use_val);
            recv_window = use_val;
        } else {
            recv_window = use_val;
        }
    }
    (void)recv_window;

    // T
    if (opt_T_str) {
        unsigned long v;
        if (parse_uint32_strict(opt_T_str, &v) != 0) {
            early_exit("Early exit: Bad maxauthtries '%s'", opt_T_str);
        }
    }
    // K
    if (opt_K_str) {
        unsigned long v;
        if (parse_uint32_strict(opt_K_str, &v) != 0) {
            early_exit("Early exit: Bad keepalive '%s'", opt_K_str);
        }
    }
    // I
    if (opt_I_str) {
