    strftime(datestr, sizeof(datestr), "%b %d %H:%M:%S", tm);
    fprintf(stderr, "[%d] %s %s\n", getpid(), datestr, msgbuf);
    fflush(stderr);
}

void early_exit(const char *fmt, ...) {
    char msgbuf[2048];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(msgbuf, sizeof(msgbuf), fmt, ap);
    va_end(ap);
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char datestr[64];
    strftime(datestr, sizeof(datestr), "%b %d %H:%M:%S", tm);
    fprintf(stderr, "[%d] %s %s\n", getpid(), datestr, msgbuf);
    fflush(stderr);
    exit(1);
}

// Strict parse for K/I/T : 0 .. 4294967295, decimal, leading spaces and + allowed, no trailing, no hex
int parse_uint32_strict(const char *s, unsigned long *out) {
    if (s == NULL || *s == '\0') return -1;
    const char *p = s;
    // skip leading spaces (isspace)
    while (*p && isspace((unsigned char)*p)) p++;
    // optional +
    if (*p == '+') p++;
    else if (*p == '-') {
        // only allow -0 variants? Actually "-0", "-00" etc should be valid as 0
        // Check if rest is all zeros
        const char *q = p+1;
        // skip? No leading spaces after -? Original allows "-0" but what about "- 0" or "- +0"? Likely not. Keep simple: after '-', must be digits
        if (*q == '\0') return -1;
        // check all remaining are digits and value is zero
        const char *r = q;
        while (*r) {
            if (!isdigit((unsigned char)*r)) return -1;
            if (*r != '0') return -1; // non-zero after minus -> invalid
            r++;
        }
        // all zeros -> valid 0
        *out = 0;
        return 0;
    }
    if (*p == '\0') return -1;
    // must be digits only, no trailing spaces
    const char *start = p;
    unsigned long long val = 0;
    int digits = 0;
    while (*p) {
        if (!isdigit((unsigned char)*p)) return -1;
        val = val*10 + (*p - '0');
        if (val > 4294967295ULL) return -1;
        p++;
        digits++;
    }
    if (digits == 0) return -1;
    *out = (unsigned long)val;
    return 0;
}

// For W: parse similarly but allow leading spaces, +, and check range
// Returns 0 valid, 1 bad (need warning), and sets *out to value to use, and *is_bad flag
// Actually we need to distinguish: valid (1..10485760, no warning), clamp (>10485760 && <=4294967295, warning with 10485760), bad (else, warning with 24576)
int parse_recv_window(const char *s, long *use_val, int *need_warning) {
    *need_warning = 0;
    *use_val = 24576;
    if (s == NULL || *s == '\0') {
        *need_warning = 1;
        *use_val = 24576;
        return 1;
    }
    const char *p = s;
    while (*p && isspace((unsigned char)*p)) p++;
    if (*p == '+') p++;
    else if (*p == '-') {
        *need_warning = 1;
        *use_val = 24576;
        // Check if string is otherwise valid? For W, "-0" is bad, so always bad for minus
        // But need to ensure message shows original s
        return 1;
    }
    if (*p == '\0') {
        *need_warning = 1;
        return 1;
    }
    // check all digits
    const char *q = p;
    while (*q) {
        if (!isdigit((unsigned char)*q)) {
            *need_warning = 1;
            return 1;
        }
        q++;
    }
    // parse with overflow check beyond 4294967295 -> bad default
    unsigned long long val = 0;
    for (const char *r = p; *r; r++) {
        val = val*10 + (*r - '0');
        if (val > 4294967295ULL) {
            *need_warning = 1;
            *use_val = 24576;
            return 1;
        }
    }
    if (val == 0) {
        *need_warning = 1;
        *use_val = 24576;
        return 1;
    }
    if (val <= 10485760ULL) {
        *use_val = (long)val;
        *need_warning = 0;
        return 0;
    } else {
        // > max but <= UINT_MAX -> clamp
        *need_warning = 1;
        *use_val = 10485760;
        return 1;
    }
}

